cd /workspace && python3 - <<'EOF'
import json, math, sys, time
print("int 4300:", end=' ')
try:
    int('1'*4300); print("ok")
except ValueError as e: print("err", e)
print("int 4301:", end=' ')
try:
    int('1'*4301); print("ok")
except ValueError as e: print("err")
print("int -4301:", end=' ')
try:
    int('-'+'1'*4301); print("ok")
except ValueError as e: print("err")
print("int 0*4301:", end=' ')
try:
    int('0'*4301); print("ok")
except ValueError as e: print("err")
print("int 0*4400:", end=' ')
try:
    int('0'*4400); print("ok")
except ValueError as e: print("err")
print(sys.int_info)
print("float 1e400:", float('1e400'))
print("float 1e-4000:", float('1e-4000'))
print("float long exp:", float('1e'+'9'*400))
# json hooks
def hook(pairs):
    d = dict(pairs)
    if len(d) != len(pairs): raise ValueError('dup')
    return d
def pf(s):
    v = float(s)
    if not math.isfinite(v): raise ValueError('inf')
    return v
try:
    print(json.loads('{"a":1,"a":2}', object_pairs_hook=hook))
except Exception as e: print("dup caught:", e)
try:
    print(json.loads('1e400', parse_float=pf))
except Exception as e: print("overflow caught:", e)
try:
    print(json.loads('NaN', parse_constant=lambda s: (_ for _ in ()).throw(ValueError('const'))))
except Exception as e: print("const caught:", e)
print(json.loads('1e-4000', parse_float=pf))
print(json.loads('[1\x0c]', object_pairs_hook=hook))
print("keys==frozenset:", {'a':1}.keys() == frozenset(('a',)))
# nesting depth scan speed
big = '['*1000 + '0' + ']'*1000
print(len(big))
EOF
